import{a as e,c as t,d as n,l as r,m as i,p as a,s as o,t as s,u as c}from"./app-BsOuDHI-.js";var l=JSON.parse(`{"path":"/documentation/quartz-4.x/how-tos/wolverine.html","title":"Quartz.NET with Wolverine","lang":"en-US","frontmatter":{"title":"Quartz.NET with Wolverine"},"git":{"updatedTime":1788441191000,"contributors":[{"name":"Marko Lahma","username":"","email":"marko.lahma@gmail.com","commits":1},{"name":"Claude Fable 5.1","username":"","email":"noreply@anthropic.com","commits":1}],"changelog":[{"hash":"8dee9f767ead84b6e47c023533864d1d3e3178ae","time":1788441191000,"email":"marko.lahma@gmail.com","author":"Marko Lahma","message":"The release post carries the day 4.0.0 shipped","coAuthors":[{"name":"Claude Fable 5.1","email":"noreply@anthropic.com"}]}]},"filePathRelative":"documentation/quartz-4.x/how-tos/wolverine.md"}`),u={name:`wolverine.md`};function d(s,l,u,d,f,p){let m=a(`RouteLink`);return n(),o(`div`,null,[l[14]||=t(`<h1 id="quartz-net-with-wolverine" tabindex="-1"><a class="header-anchor" href="#quartz-net-with-wolverine"><span>Quartz.NET with Wolverine</span></a></h1><p><a href="https://wolverinefx.net" target="_blank" rel="noopener noreferrer">Wolverine</a> can deliver a message later. It cannot say &quot;every weekday at 03:00&quot;, and its maintainer has said it never will: the request for cron scheduling, <a href="https://github.com/JasperFx/wolverine/issues/1403" target="_blank" rel="noopener noreferrer">JasperFx/wolverine#1403</a>, was closed the day it was opened with &quot;We&#39;re not doing this, ever. <em>Maybe</em> there&#39;ll be a move to integrate Quartz.net or Hangfire <em>with</em> Wolverine, but it&#39;s not something I&#39;m interested in having to support.&quot; That position has since turned into a plan rather than a refusal. Wolverine 6&#39;s <a href="https://github.com/JasperFx/wolverine/issues/2715" target="_blank" rel="noopener noreferrer">master issue</a> lists &quot;Scheduler integrations — Quartz.Net + TickerQ&quot; among its goals, its <a href="https://github.com/JasperFx/wolverine/issues/2717" target="_blank" rel="noopener noreferrer">migration-guide tracker</a> says the integrations get &quot;opt-in package references and configuration&quot; documented, the <a href="https://github.com/JasperFx/wolverine/issues/2745" target="_blank" rel="noopener noreferrer">release punchlist</a> records that the maintainer &quot;wants involvement before this lands&quot;, and the <a href="https://jeremydmiller.com/2026/07/24/critter-stack-roadmap-for-the-rest-of-2026/" target="_blank" rel="noopener noreferrer">Critter Stack roadmap post of 24 July 2026</a> says &quot;It&#39;s quite possible that Wolverine gets first class documentation and integration for Quartz.Net and TickerQ first&quot;. Wolverine has already shipped the hook the integration needs: <a href="https://wolverinefx.net/guide/messaging/message-bus.html" target="_blank" rel="noopener noreferrer">&quot;Sending Raw Message Data&quot;</a> exists, in its own words, for &quot;integrating scheduling libraries like Quartz.NET or Hangfire where you might be persisting a <code>byte[]</code> for a message to be sent via Wolverine at a certain time&quot;.</p><p>Nothing has shipped on either side. There is no <code>WolverineFx.Quartz</code> package and no <code>Quartz.Wolverine</code> package; this page is a recipe, not an announcement, and it is written against Wolverine 6.30.3.</p><div class="hint-container tip"><p class="hint-container-title">A working copy of all of this</p><p><code>src/Quartz.Examples.Wolverine</code> in the <a href="https://github.com/quartznet/quartznet/tree/main/src/Quartz.Examples.Wolverine" target="_blank" rel="noopener noreferrer">Quartz.NET repository</a> is this page as one console application that builds and runs. It is in the solution, so a call on this page that stops compiling fails the build, and every C# block below is checked against it line for line. <code>dotnet run --project src/Quartz.Examples.Wolverine -- --smoke</code> exercises all six parts against the in-memory store and exits non-zero if any of them stops working; the <code>WolverineSmoke</code> build target runs exactly that on every pull request, on all three operating systems, with no database involved.</p></div><h2 id="which-library-should-own-the-schedule" tabindex="-1"><a class="header-anchor" href="#which-library-should-own-the-schedule"><span>Which library should own the schedule</span></a></h2><p>Before wiring anything together it is worth being clear about what is genuinely missing, because most of what a bus calls &quot;scheduling&quot; is not what a scheduler does.</p><p>A transport&#39;s delay is a property of one message. Azure Service Bus says so outright: &quot;Because the feature is anchored on individual messages and messages can only be enqueued once, Service Bus doesn&#39;t support recurring schedules for messages&quot; (<a href="https://learn.microsoft.com/en-us/azure/service-bus-messaging/message-sequencing" target="_blank" rel="noopener noreferrer">message sequencing</a>). Amazon SQS caps delayed delivery at <a href="https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-delay-queues.html" target="_blank" rel="noopener noreferrer">15 minutes</a> and tells you to reach for EventBridge Scheduler beyond that. RabbitMQ&#39;s delayed-message-exchange plugin, which several buses lean on, keeps its schedule in a single unreplicated table, is documented as being for &quot;a number of seconds, minutes, or hours — a day or two at most&quot;, and <a href="https://github.com/rabbitmq/rabbitmq-delayed-message-exchange" target="_blank" rel="noopener noreferrer">is no longer maintained</a>: Mnesia was removed in RabbitMQ 4.3.0 and took the plugin with it.</p><p>A recurrence is not a message. It is a rule that outlives every message it produces, and it brings a tail of decisions with it: which time zone the expression is read in, what happens to a firing the process was down for, which node in a cluster owns it, and how it is cancelled after the fact. NServiceBus built a scheduler, ran it for years, and then removed it, publishing an unusually candid list of why: the schedule was not durable across a restart, tasks &quot;cannot be canceled or modified after creation&quot;, an interval could be specified but not an execution time, and on a scaled-out endpoint a task could be dequeued by an instance that had never created it, so it was &quot;not executed but also not rescheduled&quot;. Their conclusion was to <a href="https://docs.particular.net/nservicebus/upgrades/7to8/" target="_blank" rel="noopener noreferrer">deprecate the API</a> &quot;in favor of options like sagas and production-grade schedulers such as Hangfire, Quartz, and FluentScheduler&quot;. Rebus never offered recurrence at all, consistent with its self-description as a &quot;message bus without smarts&quot;, and <a href="https://brightercommand.gitbook.io/paramore-brighter-documentation/scheduler/brighterschedulersupport" target="_blank" rel="noopener noreferrer">Brighter</a> defines a scheduler abstraction whose whole surface is &quot;at this time&quot; and &quot;after this delay&quot;, with cron left to whichever backend it is pointed at — Quartz being one.</p><p>The honest counter-example is MassTransit, which went the other way. Having relied on Quartz for recurring messages for years — and it still ships <code>MassTransit.Quartz</code> — it grew a cron parser of its own inside its Job Service in 2024, and now <a href="https://masstransit.io/documentation/patterns/job-consumers" target="_blank" rel="noopener noreferrer">tells users</a> that &quot;Quartz.NET or Hangfire are NOT required&quot;. So this is a live disagreement, not settled practice.</p><p>The axis that decides it, in four questions:</p><ul><li>Does the schedule outlive any individual message? A rule that keeps producing work is not a delayed send, however many times you re-arm one.</li><li>Does a missed firing need a defined outcome rather than a silent drop? That decision is a misfire policy, and something has to own it.</li><li>Must the schedule be inspectable, re-schedulable and cancellable after the fact, by something other than the code that created it?</li><li>Who is on the hook when a cron expression turns out to be wrong across a daylight-saving transition? That is the maintenance surface Wolverine&#39;s maintainer declined to take on, and it is a real one.</li></ul><p>Where the answers are yes, a scheduler earns its place beside the bus. Where they are no — a saga timeout, a retry in ten minutes, a delayed reply — Wolverine&#39;s own <code>ScheduleAsync</code> is the right tool and adding Quartz buys nothing.</p><h2 id="setting-the-two-up" tabindex="-1"><a class="header-anchor" href="#setting-the-two-up"><span>Setting the two up</span></a></h2><p>Both runtimes are ordinary hosted services in one host. Wolverine goes first, so that its runtime is started before anything that might publish into it:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span><span class="token function">UseWolverine</span><span class="token punctuation">(</span>opts <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Handlers live in this assembly. Setting it explicitly rather than letting Wolverine walk the</span></span>
<span class="line">    <span class="token comment">// stack is what keeps discovery working under a test runner and under a second host in the same</span></span>
<span class="line">    <span class="token comment">// process (JasperFx/wolverine#3776, #3778).</span></span>
<span class="line">    opts<span class="token punctuation">.</span>ApplicationAssembly <span class="token operator">=</span> <span class="token keyword">typeof</span><span class="token punctuation">(</span><span class="token type-expression class-name">OrderPlaced</span><span class="token punctuation">)</span><span class="token punctuation">.</span>Assembly<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Part 3 sends raw bytes to an endpoint by name, and a name is the whole of what it can address —</span></span>
<span class="line">    <span class="token comment">// there is no live message for Wolverine to route on. A local queue keeps that free of a broker.</span></span>
<span class="line">    opts<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">PublishMessage</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ArchiveOrders<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">ToLocalQueue</span><span class="token punctuation">(</span>Part3RawMessageData<span class="token punctuation">.</span>EndpointName<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>options<span class="token punctuation">.</span>HasDatabase<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// The outbox, the inbox and the node table part 5&#39;s agent needs. Quartz&#39;s own tables go in the</span></span>
<span class="line">        <span class="token comment">// same database, because part 6&#39;s single transaction cannot span two servers.</span></span>
<span class="line">        opts<span class="token punctuation">.</span><span class="token function">PersistMessagesWithPostgresql</span><span class="token punctuation">(</span>options<span class="token punctuation">.</span>PostgresConnectionString<span class="token operator">!</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>WolverineFx.RuntimeCompilation</code> is not optional in Wolverine 6: the core package no longer ships Roslyn, and a host left in the default <code>TypeLoadMode.Dynamic</code> throws at startup with &quot;no <code>IAssemblyGenerator</code> (Roslyn) is registered&quot; unless either that package is referenced or handlers were pre-generated with <code>codegen write</code>.</p><p>Quartz is registered the way it always is. The in-memory store is the fallback, so <code>UseInMemoryStore()</code> would only restate the default; the persistent branch is what the last two sections need:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    Part1RecurringPublishing<span class="token punctuation">.</span><span class="token function">Register</span><span class="token punctuation">(</span>q<span class="token punctuation">,</span> options<span class="token punctuation">.</span>ReconciliationCron<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    Part4TunedLatency<span class="token punctuation">.</span><span class="token function">Register</span><span class="token punctuation">(</span>q<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>options<span class="token punctuation">.</span>HasDatabase<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        q<span class="token punctuation">.</span><span class="token function">UsePersistentStore</span><span class="token punctuation">(</span>store <span class="token operator">=&gt;</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            store<span class="token punctuation">.</span><span class="token function">UsePostgres</span><span class="token punctuation">(</span>options<span class="token punctuation">.</span>PostgresConnectionString<span class="token operator">!</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            store<span class="token punctuation">.</span><span class="token function">UseSystemTextJsonSerializer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">            <span class="token comment">// Development convenience. A production account is usually right not to hold DDL rights;</span></span>
<span class="line">            <span class="token comment">// database/migrations/ is what moves a real schema forward.</span></span>
<span class="line">            store<span class="token punctuation">.</span><span class="token function">ProvisionSchema</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">            <span class="token comment">// Part 6 throws without this, rather than silently scheduling outside the caller&#39;s</span></span>
<span class="line">            <span class="token comment">// transaction.</span></span>
<span class="line">            store<span class="token punctuation">.</span><span class="token function">ConfigureStore</span><span class="token punctuation">(</span>o <span class="token operator">=&gt;</span> o<span class="token punctuation">.</span>AcceptEnlistedTransactions <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Nothing else: the in-memory store is what a scheduler falls back to, so UseInMemoryStore() would</span></span>
<span class="line">    <span class="token comment">// only restate the default.</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="publishing-on-a-cron-schedule" tabindex="-1"><a class="header-anchor" href="#publishing-on-a-cron-schedule"><span>Publishing on a cron schedule</span></a></h2><p>This is the capability Wolverine does not have, and it is a job like any other. Take <code>IMessageBus</code> in the constructor — Quartz resolves the job from a fresh scope per firing, so a scoped <code>IMessageBus</code> is exactly right — and publish:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">ReconciliationJob</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJob<span class="token punctuation">&lt;</span>ReconciliationWindow<span class="token punctuation">&gt;</span></span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">readonly</span> <span class="token class-name">IMessageBus</span> bus<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">readonly</span> <span class="token class-name">ILogger<span class="token punctuation">&lt;</span>ReconciliationJob<span class="token punctuation">&gt;</span></span> logger<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token function">ReconciliationJob</span><span class="token punctuation">(</span><span class="token class-name">IMessageBus</span> bus<span class="token punctuation">,</span> <span class="token class-name">ILogger<span class="token punctuation">&lt;</span>ReconciliationJob<span class="token punctuation">&gt;</span></span> logger<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">this</span><span class="token punctuation">.</span>bus <span class="token operator">=</span> bus<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">this</span><span class="token punctuation">.</span>logger <span class="token operator">=</span> logger<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Execute</span><span class="token punctuation">(</span></span>
<span class="line">        <span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">ReconciliationWindow</span> input<span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// The scheduler&#39;s own clock, not DateTimeOffset.UtcNow: a trigger that misfired and is firing</span></span>
<span class="line">        <span class="token comment">// late still reports the time it was scheduled for, which is the window the run is about.</span></span>
<span class="line">        <span class="token class-name">DateTimeOffset</span> to <span class="token operator">=</span> context<span class="token punctuation">.</span>ScheduledFireTimeUtc <span class="token operator">??</span> context<span class="token punctuation">.</span>FireTimeUtc<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token class-name">RunReconciliation</span> message <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span>to <span class="token operator">-</span> input<span class="token punctuation">.</span>Length<span class="token punctuation">,</span> to<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">await</span> bus<span class="token punctuation">.</span><span class="token function">PublishAsync</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        logger<span class="token punctuation">.</span><span class="token function">LogInformation</span><span class="token punctuation">(</span><span class="token string">&quot;Published {Message} for the window ending {To:O}&quot;</span><span class="token punctuation">,</span> <span class="token keyword">nameof</span><span class="token punctuation">(</span>RunReconciliation<span class="token punctuation">)</span><span class="token punctuation">,</span> to<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>IJob&lt;TInput&gt;</code> is the typed-input form: the payload arrives as a parameter rather than as a <code>JobDataMap</code> lookup. Register it with a cron trigger and <code>UsingInput</code>:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">ScheduleJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ReconciliationJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>trigger <span class="token operator">=&gt;</span> trigger</span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;reconciliation&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;recurring&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span>cron<span class="token punctuation">,</span> x <span class="token operator">=&gt;</span> x</span>
<span class="line">        <span class="token comment">// The expression is read in this zone, so a deployment that means &quot;03:00 local&quot; says</span></span>
<span class="line">        <span class="token comment">// so here rather than hoping the host agrees.</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">InTimeZone</span><span class="token punctuation">(</span>TimeZoneInfo<span class="token punctuation">.</span>Utc<span class="token punctuation">)</span></span>
<span class="line">        <span class="token comment">// What happens when the process was down at 03:00. DoNothing skips to the next</span></span>
<span class="line">        <span class="token comment">// firing; FireAndProceed publishes one catch-up message. Wolverine has no equivalent</span></span>
<span class="line">        <span class="token comment">// decision to make, because it has nothing to miss.</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">WithMisfireInstruction</span><span class="token punctuation">(</span>CronTriggerMisfireInstruction<span class="token punctuation">.</span>DoNothing<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">UsingInput</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">ReconciliationWindow</span><span class="token punctuation">(</span>TimeSpan<span class="token punctuation">.</span><span class="token function">FromDays</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Read <code>context.ScheduledFireTimeUtc</code> rather than the clock. A trigger firing late after a misfire still reports the time it was scheduled for, and that is the window the run is about.</p><h2 id="scheduling-one-firing-from-a-handler" tabindex="-1"><a class="header-anchor" href="#scheduling-one-firing-from-a-handler"><span>Scheduling one firing from a handler</span></a></h2><p>A Wolverine handler can take <code>IScheduler</code> as a parameter and arrange a single future firing in one call. <code>OneOffJobOptions.Group</code> is the interesting argument: it sets the trigger&#39;s group, and the group is a correlation axis — everything scheduled for one order, one saga or one tenant shares it.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">class</span> <span class="token class-name">OrderPlacedHandler</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">async</span> <span class="token return-type class-name">Task</span> <span class="token function">Handle</span><span class="token punctuation">(</span><span class="token class-name">OrderPlaced</span> message<span class="token punctuation">,</span> <span class="token class-name">IScheduler</span> scheduler<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">ScheduledOneOffJob</span> scheduled <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">ScheduleJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>PaymentReminderJob<span class="token punctuation">,</span> PaymentReminder<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span></span>
<span class="line">            <span class="token keyword">new</span> <span class="token constructor-invocation class-name">PaymentReminder</span><span class="token punctuation">(</span>message<span class="token punctuation">.</span>OrderId<span class="token punctuation">,</span> message<span class="token punctuation">.</span>Amount<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            ExampleOptions<span class="token punctuation">.</span>Current<span class="token punctuation">.</span>ReminderDelay<span class="token punctuation">,</span></span>
<span class="line">            <span class="token keyword">new</span> <span class="token constructor-invocation class-name">OneOffJobOptions</span> <span class="token punctuation">{</span> Group <span class="token operator">=</span> OrderGroup<span class="token punctuation">.</span><span class="token function">For</span><span class="token punctuation">(</span>message<span class="token punctuation">.</span>OrderId<span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">            cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// The call answers with the trigger&#39;s key and the time the store says it will first fire, so</span></span>
<span class="line">        <span class="token comment">// &quot;scheduled for&quot; is what will happen rather than what was asked for.</span></span>
<span class="line">        Ledger<span class="token punctuation">.</span><span class="token function">Record</span><span class="token punctuation">(</span>Events<span class="token punctuation">.</span>ReminderScheduled<span class="token punctuation">,</span> <span class="token interpolation-string"><span class="token string">$&quot;</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">scheduled<span class="token punctuation">.</span>TriggerKey</span><span class="token punctuation">}</span></span><span class="token string"> at </span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">scheduled<span class="token punctuation">.</span>FirstFireTimeUtc</span><span class="token format-string"><span class="token punctuation">:</span>u</span><span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The job key is not affected by <code>Group</code>. One durable job detail is stored per job type, under the <code>QRTZ_SCHEDULED</code> group, and each call adds a trigger to it; the group you pass names the trigger.</p><h3 id="cancelling-by-correlation" tabindex="-1"><a class="header-anchor" href="#cancelling-by-correlation"><span>Cancelling by correlation</span></a></h3><p>Because the group is part of the trigger&#39;s identity, withdrawing everything arranged for one order is a single store operation, with the matcher evaluated where the triggers are:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">class</span> <span class="token class-name">OrderPaidHandler</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">async</span> <span class="token return-type class-name">Task</span> <span class="token function">Handle</span><span class="token punctuation">(</span><span class="token class-name">OrderPaid</span> message<span class="token punctuation">,</span> <span class="token class-name">IScheduler</span> scheduler<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// The whole cancellation, in one store operation. The matcher is evaluated where the triggers</span></span>
<span class="line">        <span class="token comment">// are, so no key list round-trips through this process and there is no window in which a</span></span>
<span class="line">        <span class="token comment">// trigger listed a moment ago fires before it can be removed. What comes back is the keys that</span></span>
<span class="line">        <span class="token comment">// were actually withdrawn, which is how the caller learns whether it beat the firing.</span></span>
<span class="line">        <span class="token class-name">List<span class="token punctuation">&lt;</span>TriggerKey<span class="token punctuation">&gt;</span></span> cancelled <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">UnscheduleJobs</span><span class="token punctuation">(</span></span>
<span class="line">            GroupMatcher<span class="token operator">&lt;</span>TriggerKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupEquals</span><span class="token punctuation">(</span>OrderGroup<span class="token punctuation">.</span><span class="token function">For</span><span class="token punctuation">(</span>message<span class="token punctuation">.</span>OrderId<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        Ledger<span class="token punctuation">.</span><span class="token function">Record</span><span class="token punctuation">(</span>Events<span class="token punctuation">.</span>RemindersCancelled<span class="token punctuation">,</span> <span class="token interpolation-string"><span class="token string">$&quot;</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">cancelled<span class="token punctuation">.</span>Count</span><span class="token punctuation">}</span></span><span class="token string"> for </span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">message<span class="token punctuation">.</span>OrderId</span><span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>This is worth comparing honestly with the alternatives, because &quot;Quartz can cancel and buses cannot&quot; would be wrong. Azure Service Bus hands back a sequence number and takes it back through <code>CancelScheduledMessageAsync</code>; MassTransit gives you a <code>TokenId</code> and a <code>CancelScheduledMessage</code> contract; Hangfire returns a job id for <code>BackgroundJob.Delete</code>. What none of them offers is a <em>set</em> operation. Each cancels exactly one schedule per call, against a handle the application had to keep. Quartz&#39;s schedule identity is a two-part key, and the scheduler exposes group matchers over it — <code>GetTriggerKeys</code>, <code>UnscheduleJobs</code>, <code>PauseTriggerGroups</code>, <code>DeleteJobs</code> — so &quot;everything this tenant owns&quot; is a query rather than a list you were responsible for not losing. NServiceBus saga timeouts sit at the other end: they cannot be cancelled at all, and the documented approach is to let the timeout arrive and be ignored because the saga is gone.</p><h2 id="deferring-a-serialized-envelope" tabindex="-1"><a class="header-anchor" href="#deferring-a-serialized-envelope"><span>Deferring a serialized envelope</span></a></h2><p>The section of Wolverine&#39;s documentation that names Quartz teaches <code>SendRawMessageAsync</code>, which takes a <code>byte[]</code> rather than a message. What it does not show is how to produce the bytes, or where to keep them; <code>WolverineOptions.DefaultSerializer.WriteMessage(message)</code> is the missing line, and a typed job input is the place:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask<span class="token punctuation">&lt;</span>TriggerKey<span class="token punctuation">&gt;</span></span> <span class="token generic-method"><span class="token function">ScheduleSend</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>TMessage<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span></span>
<span class="line">    <span class="token class-name">IScheduler</span> scheduler<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">IWolverineRuntime</span> runtime<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">TMessage</span> message<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">TimeSpan</span> delay<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span> <span class="token keyword">where</span> <span class="token class-name">TMessage</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token keyword">notnull</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Serialized here, at the moment the decision was made, rather than at fire time.</span></span>
<span class="line">    <span class="token class-name">DeferredEnvelope</span> envelope <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span></span>
<span class="line">        EndpointName<span class="token punctuation">,</span></span>
<span class="line">        <span class="token keyword">typeof</span><span class="token punctuation">(</span><span class="token type-expression class-name">TMessage</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">ToMessageTypeName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        runtime<span class="token punctuation">.</span>Options<span class="token punctuation">.</span>DefaultSerializer<span class="token punctuation">.</span><span class="token function">WriteMessage</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token class-name">ScheduledOneOffJob</span> scheduled <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">ScheduleJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>DeferredEnvelopeJob<span class="token punctuation">,</span> DeferredEnvelope<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span></span>
<span class="line">        envelope<span class="token punctuation">,</span></span>
<span class="line">        delay<span class="token punctuation">,</span></span>
<span class="line">        <span class="token keyword">new</span> <span class="token constructor-invocation class-name">OneOffJobOptions</span> <span class="token punctuation">{</span> Group <span class="token operator">=</span> <span class="token string">&quot;deferred-envelopes&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">        cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> scheduled<span class="token punctuation">.</span>TriggerKey<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>At fire time the job hands the stored bytes back to Wolverine:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Execute</span><span class="token punctuation">(</span></span>
<span class="line">    <span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">DeferredEnvelope</span> input<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">IDestinationEndpoint</span> endpoint <span class="token operator">=</span> bus<span class="token punctuation">.</span><span class="token function">EndpointFor</span><span class="token punctuation">(</span>input<span class="token punctuation">.</span>EndpointName<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">await</span> endpoint<span class="token punctuation">.</span><span class="token function">SendRawMessageAsync</span><span class="token punctuation">(</span>input<span class="token punctuation">.</span>Data<span class="token punctuation">,</span> <span class="token named-parameter punctuation">configure</span><span class="token punctuation">:</span> envelope <span class="token operator">=&gt;</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// The stored name rather than SetMessageType&lt;T&gt;(): the type this envelope describes is</span></span>
<span class="line">        <span class="token comment">// whatever was serialized, which this job has no static knowledge of.</span></span>
<span class="line">        envelope<span class="token punctuation">.</span>MessageType <span class="token operator">=</span> input<span class="token punctuation">.</span>MessageTypeName<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// Setting Destination is not optional, and Wolverine 6.30.3 does not do it for you.</span></span>
<span class="line">        <span class="token comment">// DestinationEndpoint.SendRawMessageAsync assigns Sender but leaves Destination null, and</span></span>
<span class="line">        <span class="token comment">// Executor.ExecuteAsync logs both success and failure through envelope.Destination!, so a</span></span>
<span class="line">        <span class="token comment">// raw message that is handled perfectly still ends the pipeline with a</span></span>
<span class="line">        <span class="token comment">// NullReferenceException out of the logging call. One line here avoids it.</span></span>
<span class="line">        envelope<span class="token punctuation">.</span>Destination <span class="token operator">=</span> endpoint<span class="token punctuation">.</span>Uri<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Two things are load-bearing there. <code>Envelope.MessageType</code> is set from the stored name rather than from <code>SetMessageType&lt;T&gt;()</code>, because the job has no static knowledge of what was serialized; <code>typeof(T).ToMessageTypeName()</code> on the storing side honours a <code>[MessageIdentity]</code> alias where a raw <code>FullName</code> would not. And <code>Envelope.Destination</code> has to be set by hand: on Wolverine 6.30.3, <code>SendRawMessageAsync</code> assigns <code>Sender</code> but leaves <code>Destination</code> null, while <code>Executor.ExecuteAsync</code> logs both success and failure through <code>envelope.Destination!</code> — so a raw message that is handled perfectly still ends its pipeline with a <code>NullReferenceException</code> out of the logging call.</p><p>Why bother, when the previous section publishes a live object instead? Because the envelope is serialized at the moment the decision was made. A payload stored as bytes is not re-derived from application state that has since moved on, and the message contract can change under it without the stored firing changing meaning. It is the outbox argument, applied to a schedule.</p><h2 id="what-the-latency-settings-actually-do" tabindex="-1"><a class="header-anchor" href="#what-the-latency-settings-actually-do"><span>What the latency settings actually do</span></a></h2><p>Reading Quartz&#39;s 30-second <code>IdleWaitTime</code> beside Wolverine&#39;s 5-second <code>ScheduledJobPollingTime</code> invites the conclusion that Quartz is six times slower to deliver a due message. That is not what the numbers mean.</p><p><code>QuartzSchedulerThread</code> acquires triggers due within the next <code>IdleWaitTime</code>, not triggers due now, and having acquired one it waits out the exact fire time rather than sleeping the interval. More importantly, every in-process mutation — <code>ScheduleJob</code>, <code>AddTrigger</code>, <code>RescheduleJob</code>, <code>DeleteJob</code> — signals the scheduling loop, which releases the wait immediately. A trigger scheduled from a Wolverine handler through this process&#39;s own <code>IScheduler</code> therefore does not wait for a sweep at all.</p><p><code>IdleWaitTime</code> bounds the discovery of work this node did not learn about in process: a trigger another node wrote to the shared database, or one recovered from a node that died. It is a cross-node pickup bound and the look-ahead horizon of a single acquisition. Lowering it does not make a locally scheduled job fire sooner, and the one place it genuinely shows is the last section on this page.</p><p>With that said, the three settings that are worth touching in front of a message bus:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token function">ConfigureScheduler</span><span class="token punctuation">(</span>options <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Default 30 s. Only affects how quickly this node notices triggers it did not schedule</span></span>
<span class="line">    <span class="token comment">// itself, so it is a clustering setting, not a latency setting.</span></span>
<span class="line">    options<span class="token punctuation">.</span>IdleWaitTime <span class="token operator">=</span> TimeSpan<span class="token punctuation">.</span><span class="token function">FromSeconds</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Default 1. Must not exceed ThreadPoolOptions.MaxConcurrency, which defaults to 10.</span></span>
<span class="line">    options<span class="token punctuation">.</span>MaxBatchSize <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Default TimeSpan.Zero. Without this, MaxBatchSize above changes nothing for triggers</span></span>
<span class="line">    <span class="token comment">// that are due milliseconds apart rather than at the same instant.</span></span>
<span class="line">    options<span class="token punctuation">.</span>BatchTriggerAcquisitionFireAheadTimeWindow <span class="token operator">=</span> TimeSpan<span class="token punctuation">.</span><span class="token function">FromMilliseconds</span><span class="token punctuation">(</span><span class="token number">500</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>MaxBatchSize</code> and <code>BatchTriggerAcquisitionFireAheadTimeWindow</code> are one setting in two halves. With the default window of <code>TimeSpan.Zero</code> only triggers due at the same instant batch together, so raising <code>MaxBatchSize</code> alone leaves the effective batch at one for any schedule spread over time. Set the window to the spread you are willing to fire early by. <code>MaxBatchSize</code> must not exceed the thread pool&#39;s <code>MaxConcurrency</code>, and <code>IdleWaitTime</code> has a floor of one second.</p><h2 id="letting-wolverine-start-the-scheduler" tabindex="-1"><a class="header-anchor" href="#letting-wolverine-start-the-scheduler"><span>Letting Wolverine start the scheduler</span></a></h2><p><code>AutoStart = false</code> leaves the scheduler built, initialized and bound but in <code>SchedulerStatus.Created</code>. Everything that reads a scheduler still sees it; nothing fires until something calls <code>Start</code>. Shutdown is unaffected — the hosted service stops every scheduler it created, started or not.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span>Services<span class="token punctuation">.</span><span class="token function">AddQuartzHostedService</span><span class="token punctuation">(</span>hosted <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    hosted<span class="token punctuation">.</span>AutoStart <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line">    hosted<span class="token punctuation">.</span>WaitForJobsToComplete <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Which &quot;something&quot; presses start depends on whether Wolverine has a message store, and here the tidy answer and the true one differ.</p><p><strong>Without persistence</strong>, Wolverine runs no agents at all. <code>WolverineRuntime.startAgentsAsync</code> opens with <code>if (Storage is NullMessageStore) { ...; return; }</code>, so the node agent controller is never built and the <code>IAgentFamily</code> registrations in the container are never read. <code>AddSingularAgent&lt;T&gt;()</code> would compile, register, and silently never start. The faithful form is an ordinary <code>IHostedService</code> registered after <code>UseWolverine</code>, since hosted services start in registration order:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">SchedulerStarter</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IHostedService</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">readonly</span> <span class="token class-name">ISchedulerFactory</span> schedulerFactory<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">readonly</span> <span class="token class-name">ILogger<span class="token punctuation">&lt;</span>SchedulerStarter<span class="token punctuation">&gt;</span></span> logger<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token function">SchedulerStarter</span><span class="token punctuation">(</span><span class="token class-name">ISchedulerFactory</span> schedulerFactory<span class="token punctuation">,</span> <span class="token class-name">ILogger<span class="token punctuation">&lt;</span>SchedulerStarter<span class="token punctuation">&gt;</span></span> logger<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">this</span><span class="token punctuation">.</span>schedulerFactory <span class="token operator">=</span> schedulerFactory<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">this</span><span class="token punctuation">.</span>logger <span class="token operator">=</span> logger<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">Task</span> <span class="token function">StartAsync</span><span class="token punctuation">(</span><span class="token class-name">CancellationToken</span> cancellationToken<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">IScheduler</span> scheduler <span class="token operator">=</span> <span class="token keyword">await</span> schedulerFactory<span class="token punctuation">.</span><span class="token function">GetScheduler</span><span class="token punctuation">(</span>cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">Start</span><span class="token punctuation">(</span>cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        logger<span class="token punctuation">.</span><span class="token function">LogInformation</span><span class="token punctuation">(</span><span class="token string">&quot;Scheduler &#39;{Name}&#39; started after the Wolverine runtime&quot;</span><span class="token punctuation">,</span> scheduler<span class="token punctuation">.</span>SchedulerName<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        Ledger<span class="token punctuation">.</span><span class="token function">Record</span><span class="token punctuation">(</span>Events<span class="token punctuation">.</span>SchedulerStartedByWolverine<span class="token punctuation">,</span> <span class="token string">&quot;IHostedService ordered after UseWolverine&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Nothing to do: the Quartz hosted service shuts the scheduler down whether or not it started it.</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name">Task</span> <span class="token function">StopAsync</span><span class="token punctuation">(</span><span class="token class-name">CancellationToken</span> cancellationToken<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> Task<span class="token punctuation">.</span>CompletedTask<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>With persistence</strong>, the agent machinery is running and <code>SingularAgent</code> is the supported way to say &quot;one node in the cluster does this&quot;:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">protected</span> <span class="token keyword">override</span> <span class="token keyword">async</span> <span class="token return-type class-name">Task</span> <span class="token function">startAsync</span><span class="token punctuation">(</span><span class="token class-name">CancellationToken</span> cancellationToken<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    started <span class="token operator">=</span> <span class="token keyword">await</span> schedulerFactory<span class="token punctuation">.</span><span class="token function">GetScheduler</span><span class="token punctuation">(</span>cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">await</span> started<span class="token punctuation">.</span><span class="token function">Start</span><span class="token punctuation">(</span>cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    logger<span class="token punctuation">.</span><span class="token function">LogInformation</span><span class="token punctuation">(</span><span class="token string">&quot;Scheduler &#39;{Name}&#39; started on this node by Wolverine&quot;</span><span class="token punctuation">,</span> started<span class="token punctuation">.</span>SchedulerName<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    Ledger<span class="token punctuation">.</span><span class="token function">Record</span><span class="token punctuation">(</span>Events<span class="token punctuation">.</span>SchedulerStartedByWolverine<span class="token punctuation">,</span> <span class="token string">&quot;Wolverine SingularAgent&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">protected</span> <span class="token keyword">override</span> <span class="token keyword">async</span> <span class="token return-type class-name">Task</span> <span class="token function">stopAsync</span><span class="token punctuation">(</span><span class="token class-name">CancellationToken</span> cancellationToken<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// The scheduler the agent started, not a fresh ISchedulerFactory.GetScheduler(): on host</span></span>
<span class="line">    <span class="token comment">// shutdown Wolverine stops its agents after the Quartz hosted service has already shut the</span></span>
<span class="line">    <span class="token comment">// scheduler down, and asking the factory for it again throws rather than handing back the</span></span>
<span class="line">    <span class="token comment">// shut-down instance. Holding the reference and checking Status keeps the stop quiet.</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>started <span class="token keyword">is</span> <span class="token keyword">null</span> <span class="token operator">||</span> started<span class="token punctuation">.</span>Status <span class="token keyword">is</span> <span class="token class-name">SchedulerStatus<span class="token punctuation">.</span>ShuttingDown</span> <span class="token keyword">or</span> SchedulerStatus<span class="token punctuation">.</span>Shutdown<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Standby rather than Shutdown: the agent may be re-assigned to this node later, and a</span></span>
<span class="line">    <span class="token comment">// shut-down scheduler cannot be started again in the same container.</span></span>
<span class="line">    <span class="token keyword">await</span> started<span class="token punctuation">.</span><span class="token function">Standby</span><span class="token punctuation">(</span>cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Be precise about what that buys. <code>SingularAgent</code> is once-per-cluster but it is <em>not</em> leader-pinned: its <code>EvaluateAssignmentsAsync</code> picks <code>assignments.Nodes.FirstOrDefault(x =&gt; !x.IsLeader) ?? assignments.Nodes.FirstOrDefault()</code>, so it prefers a non-leader and falls back to the leader only when there is one node. Wolverine&#39;s own leader-pinned family is for transport listeners and is registered internally; a user cannot add to it. Strictly-leader-only means writing an <code>IAgentFamily</code> of your own and calling <code>AssignmentGrid.RunOnLeader</code>.</p><p>Note also what is <em>not</em> being asked of Wolverine here: not &quot;which node may fire this trigger&quot;. A clustered persistent Quartz store already answers that with its own lock, so a scheduler running on every node still fires each trigger once. What this arrangement buys is that the scheduler&#39;s lifecycle is subordinate to the messaging runtime&#39;s — the bus is up before the first job can publish into it.</p><h2 id="sharing-the-outbox-s-transaction" tabindex="-1"><a class="header-anchor" href="#sharing-the-outbox-s-transaction"><span>Sharing the outbox&#39;s transaction</span></a></h2><p>A handler that writes a row, sends a message and schedules a follow-up has three writes that can disagree. Wolverine&#39;s outbox already ties the first two together. <code>IScheduler.EnlistTransaction</code> is how the third joins them: for the duration of the returned scope, on the current asynchronous flow, the persistent job store uses the given transaction and its connection instead of opening its own, so the <code>INSERT</code> into <code>QRTZ_TRIGGERS</code> is a statement in the caller&#39;s transaction and a rollback takes the trigger with it.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">async</span> <span class="token return-type class-name">Task</span> <span class="token function">Handle</span><span class="token punctuation">(</span></span>
<span class="line">    <span class="token class-name">ApproveRefund</span> message<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">MessageContext</span> context<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">IWolverineRuntime</span> runtime<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">IScheduler</span> scheduler<span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">CancellationToken</span> cancellationToken<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">IMessageDatabase</span> database <span class="token operator">=</span> <span class="token punctuation">(</span>IMessageDatabase<span class="token punctuation">)</span> runtime<span class="token punctuation">.</span>Storage<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">await</span> <span class="token keyword">using</span> <span class="token class-name">NpgsqlConnection</span> connection <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span>ExampleOptions<span class="token punctuation">.</span>Current<span class="token punctuation">.</span>PostgresConnectionString<span class="token operator">!</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">await</span> connection<span class="token punctuation">.</span><span class="token function">OpenAsync</span><span class="token punctuation">(</span>cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">await</span> <span class="token keyword">using</span> <span class="token class-name">DbTransaction</span> transaction <span class="token operator">=</span> <span class="token keyword">await</span> connection<span class="token punctuation">.</span><span class="token function">BeginTransactionAsync</span><span class="token punctuation">(</span>cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Wolverine&#39;s outgoing envelopes are now written into this transaction rather than sent</span></span>
<span class="line">    <span class="token comment">// immediately. This is the manual form of what [Transactional] does for a Marten or EF Core</span></span>
<span class="line">    <span class="token comment">// application.</span></span>
<span class="line">    <span class="token keyword">await</span> context<span class="token punctuation">.</span><span class="token function">EnlistInOutboxAsync</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">DatabaseEnvelopeTransaction</span><span class="token punctuation">(</span>database<span class="token punctuation">,</span> transaction<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 1. the application&#39;s own state</span></span>
<span class="line">    <span class="token keyword">await</span> <span class="token keyword">using</span> <span class="token punctuation">(</span><span class="token class-name">NpgsqlCommand</span> command <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span></span>
<span class="line">        <span class="token string">&quot;insert into refunds (order_id, amount) values (@order_id, @amount)&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        connection<span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">(</span>NpgsqlTransaction<span class="token punctuation">)</span> transaction<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        command<span class="token punctuation">.</span>Parameters<span class="token punctuation">.</span><span class="token function">AddWithValue</span><span class="token punctuation">(</span><span class="token string">&quot;order_id&quot;</span><span class="token punctuation">,</span> message<span class="token punctuation">.</span>OrderId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        command<span class="token punctuation">.</span>Parameters<span class="token punctuation">.</span><span class="token function">AddWithValue</span><span class="token punctuation">(</span><span class="token string">&quot;amount&quot;</span><span class="token punctuation">,</span> message<span class="token punctuation">.</span>Amount<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">await</span> command<span class="token punctuation">.</span><span class="token function">ExecuteNonQueryAsync</span><span class="token punctuation">(</span>cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 2. a message that must not be sent unless the row above survives</span></span>
<span class="line">    <span class="token keyword">await</span> context<span class="token punctuation">.</span><span class="token function">PublishAsync</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">SendPaymentReminder</span><span class="token punctuation">(</span>message<span class="token punctuation">.</span>OrderId<span class="token punctuation">,</span> message<span class="token punctuation">.</span>Amount<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 3. the trigger, in the same transaction as both, with the commit inside the scope so the</span></span>
<span class="line">    <span class="token comment">// scheduler is signalled once the trigger is visible to it</span></span>
<span class="line">    <span class="token keyword">using</span> <span class="token punctuation">(</span>scheduler<span class="token punctuation">.</span><span class="token function">EnlistTransaction</span><span class="token punctuation">(</span>transaction<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">ScheduleJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>PaymentReminderJob<span class="token punctuation">,</span> PaymentReminder<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span></span>
<span class="line">            <span class="token keyword">new</span> <span class="token constructor-invocation class-name">PaymentReminder</span><span class="token punctuation">(</span>message<span class="token punctuation">.</span>OrderId<span class="token punctuation">,</span> message<span class="token punctuation">.</span>Amount<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            TimeSpan<span class="token punctuation">.</span><span class="token function">FromDays</span><span class="token punctuation">(</span><span class="token number">7</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token keyword">new</span> <span class="token constructor-invocation class-name">OneOffJobOptions</span> <span class="token punctuation">{</span> Group <span class="token operator">=</span> OrderGroup<span class="token punctuation">.</span><span class="token function">For</span><span class="token punctuation">(</span>message<span class="token punctuation">.</span>OrderId<span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">            cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">await</span> transaction<span class="token punctuation">.</span><span class="token function">CommitAsync</span><span class="token punctuation">(</span>cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Releases the envelopes the outbox held back. Nothing left the process before the commit.</span></span>
<span class="line">    <span class="token keyword">await</span> context<span class="token punctuation">.</span><span class="token function">FlushOutgoingMessagesAsync</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    Ledger<span class="token punctuation">.</span><span class="token function">Record</span><span class="token punctuation">(</span>Events<span class="token punctuation">.</span>RefundApprovedInTransaction<span class="token punctuation">,</span> message<span class="token punctuation">.</span>OrderId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The caveats are all in <a href="https://github.com/quartznet/quartznet/blob/main/src/Quartz/SchedulerEnlistmentExtensions.cs" target="_blank" rel="noopener noreferrer"><code>SchedulerEnlistmentExtensions</code></a>&#39; own documentation, and every one of them bites here:</p><ul><li>It must be turned on. <code>ConfigureStore(o =&gt; o.AcceptEnlistedTransactions = true)</code>, or <code>quartz.jobStore.acceptEnlistedTransactions</code>. Without it &quot;the job store keeps opening its own connection and managing its own transaction, and enlisting throws rather than being ignored&quot;.</li><li>An ambient <code>TransactionScope</code> on its own is not enough, &quot;because a connection the job store opens for itself is deliberately kept out of it&quot;. Sharing the one connection is also what keeps the transaction from being promoted to a distributed one, which Npgsql does not support at all.</li><li>The enlistment &quot;flows with the current asynchronous context, so it must be established in the same scope as the scheduler calls it should cover&quot;. Establishing it inside an <code>async</code> helper does not carry it back out to the caller.</li><li>The commit belongs inside the <code>using</code> block. Disposing the scope is what signals the scheduling loop that a trigger appeared, so disposing before the commit wakes it to look for a row it cannot yet see — and the trigger then waits for the next acquisition sweep, which is one of the few places <code>IdleWaitTime</code> really does bound latency.</li><li>&quot;While the enlistment is in effect the job store holds its locks in the caller&#39;s transaction, so they are only released once that transaction completes. Keep enlisted transactions short: a long running one blocks trigger acquisition, the misfire handler and cluster check-in.&quot; A message handler fits that; a batch job that enlists and then works for a minute does not.</li><li>Both stores must be in one database. Different schemas are fine; one <code>DbTransaction</code> cannot span two servers.</li></ul><p>The transaction is opened by hand rather than by Wolverine&#39;s <code>[Transactional]</code> attribute, and that is not a stylistic choice. Wolverine&#39;s transactional middleware supplies whatever its persistence provider supplies, and on 6.30.3 the raw-ADO.NET Postgres package supplies nothing: every <code>IPersistenceFrameProvider</code> in the tree belongs to Marten, Entity Framework Core, RavenDB, CosmosDB, Fisher or Polecat. A handler declaring <code>[Transactional] Handle(T msg, NpgsqlTransaction tx)</code> against plain <code>PersistMessagesWithPostgresql</code> compiles and then fails at runtime with &quot;JasperFx was unable to resolve a variable of type Npgsql.NpgsqlTransaction&quot;. An application that already has Marten or EF Core can use <code>[Transactional]</code> and take the provider&#39;s own session or <code>DbContext</code> — but then the commit happens in generated code after the handler returns, so the enlistment scope necessarily disposes first, and the signal is spent on a trigger the loop cannot yet see. Nothing is lost; the trigger simply waits for the next sweep.</p><h2 id="what-this-recipe-does-not-do" tabindex="-1"><a class="header-anchor" href="#what-this-recipe-does-not-do"><span>What this recipe does not do</span></a></h2><ul><li><strong>It is not a package.</strong> There is nothing to install beyond <code>Quartz</code> and <code>WolverineFx</code>, and nothing here is covered by Quartz.NET&#39;s API compatibility promises. If JasperFx ships a first-party integration, prefer it.</li><li><strong>It does not put Quartz&#39;s schedule under Wolverine&#39;s leader election.</strong> Trigger ownership is the Quartz cluster&#39;s business, and a persistent store with <code>UseClustering()</code> already handles it. The agent in the last-but-one section decides which node <em>runs a scheduler</em>, not which node fires a trigger.</li><li><strong>It does not make in-memory scheduling durable.</strong> With the default in-memory store a restart loses every pending trigger, exactly as it loses Wolverine&#39;s in-memory scheduled envelopes. Use a persistent store for anything that must survive.</li><li><strong>It does not replace Wolverine&#39;s own scheduling.</strong> <code>ScheduleAsync</code> and <code>TimeoutMessage</code> remain the right answer for a delayed message or a saga timeout. Reach for Quartz when the schedule is a rule rather than a message.</li></ul><h2 id="see-also" tabindex="-1"><a class="header-anchor" href="#see-also"><span>See also</span></a></h2>`,65),e(`ul`,null,[e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/how-tos/one-off-job.html`},{default:i(()=>[...l[0]||=[r(`One-Off Job`,-1)]]),_:1}),l[1]||=r(` — the `,-1),l[2]||=e(`code`,null,`ScheduleJob<TJob, TInput>`,-1),l[3]||=r(` one-liner in isolation`,-1)]),e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/how-tos/rescheduling-jobs.html`},{default:i(()=>[...l[4]||=[r(`Rescheduling Jobs`,-1)]]),_:1}),l[5]||=r(` — changing a live schedule, and recovering a failed trigger`,-1)]),e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/how-tos/job-template.html`},{default:i(()=>[...l[6]||=[r(`Job Template`,-1)]]),_:1}),l[7]||=r(` — the recommended skeleton for a job class`,-1)]),e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/how-tos/aspire.html`},{default:i(()=>[...l[8]||=[r(`Running Quartz under Aspire`,-1)]]),_:1}),l[9]||=r(` — telemetry, health and the database, wired to an AppHost`,-1)]),e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/cron-expressions.html`},{default:i(()=>[...l[10]||=[r(`Cron Expression Reference`,-1)]]),_:1}),l[11]||=r(` — the cron field and special-character syntax`,-1)]),e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/configuration/reference.html`},{default:i(()=>[...l[12]||=[r(`Configuration Reference`,-1)]]),_:1}),l[13]||=r(` — every option, typed and legacy`,-1)])])])}var f=s(u,[[`render`,d]]);export{l as _pageData,f as default};